    if (o.faceAt) { cx = o.faceAt[0]; cy = o.faceAt[1] + (yf - TH); }
    else if (mode === 'stack') { cx = w / 2 + (o.faceDx || 0); cy = yf + 31; }
    else if (mode === 'line') { cx = 46; cy = (yf + h) / 2 + 1; }
    else { cx = w / 2 + (o.faceDx || 0); cy = yf + (h - yf) * .5 + 1; }
