    if (mode === 'stack' && label) {
      const ws = label.split(' ');
      if (ws.length > 1) {
        s += text(ws[0], xh * 1.04, { x: 10, y: h - 25.5, jitter: .45, seed: 3, fill: ink, cls: 'lbl' }).svg;
        s += text(ws.slice(1).join(' '), xh * 1.04, { x: 10, y: h - 7.2, jitter: .45, seed: 7, fill: ink, cls: 'lbl' }).svg;
      } else s += text(label, xh * 1.04, { x: 10, y: h - 7.2, jitter: .45, seed: 3, fill: ink, cls: 'lbl' }).svg;
    } else if (mode === 'line' && label) {
      s += text(label, xh, { x: 92, y: (yf + h) / 2 + xh / 2 - .4, jitter: .4, seed: 5, fill: ink, cls: 'lbl' }).svg;
    }
